/**
 * @param {VNodeRecord} parent
 * @param {import('../internal').VNode[]} slots
 */
function ChildNormalizer(parent, slots) {
	this.parent = parent;
	this.slots = slots;
}

/**
 * Coerce a raw child value into a vnode owned by the parent.
 * @param {import('../internal').ComponentChildren} childVNode
 * @param {number} i
 * @returns {import('../internal').VNode | null}
 */
ChildNormalizer.prototype.coerceChild = function(childVNode, i) {
	if (childVNode == null || typeof childVNode == 'boolean') {
		childVNode = this.slots[i] = null;
	}
	// If this newVNode is being reused (e.g. <div>{reuse}{reuse}</div>) in the same diff,
	// or we are rendering a component (e.g. setState) copy the oldVNodes so it can have
	// it's own DOM & etc. pointers
	else if (typeof childVNode == 'string' || typeof childVNode == 'number') {
		childVNode = this.slots[i] = createVNode(
			null,
			childVNode,
			null,
			null,
			childVNode
		);
	} else if (Array.isArray(childVNode)) {
		childVNode = this.slots[i] = createVNode(
			Fragment,
			{ children: childVNode },
			null,
			null,
			null
		);
	} else {
		let record = new VNodeRecord(childVNode);
		if (record._depth > 0) {
			// VNode is already in use, clone it. This can happen in the following
			// scenario:
			//   const reuse = <div />
			//   <div>{reuse}<span />{reuse}</div>
			childVNode = this.slots[i] = createVNode(
				record.type,
				record.props,
				record.key,
				null,
				record._original
			);
		} else {
			childVNode = this.slots[i] = childVNode;
		}
	}

	if (childVNode != null) {
		childVNode._depth = this.parent._depth + 1;
	}

	return childVNode;
};

/**
 * Flatten and loop through the children of a virtual node
 * @param {import('../index').ComponentChildren} children The unflattened
 * children of a virtual node
 * @returns {import('../internal').VNode[]}
 */
